 document.querySelectorAll('#app-shell .care-symbol,#app-shell .record-icon,#app-shell .symbol,#app-shell .nav-symbol').forEach(el=>{const text=el.textContent.trim(),mapping={'＋':'fuel','+':'plus','⌁':'service','⚙':'part','◒':'oil','⌖':'pin','▤':'document','◷':'history','⌂':'garage'};if(mapping[text])el.innerHTML=icon(mapping[text]);});
